SELECT count(*) AS total, sum(CASE WHEN (q.t0 = :one AND q.t0 = :one AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one)) THEN :one ELSE :zero END) AS m0, sum(CASE WHEN (q.t1 = :one AND q.t0 = :one AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one) AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one)) THEN :one ELSE :zero END) AS m1, sum(CASE WHEN (q.t2 = :one AND q.t0 = :one AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one) AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one)) THEN :one ELSE :zero END) AS m2, sum(CASE WHEN (q.t3 = :one AND q.t0 = :one AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one) AND (q.t1 = :one OR q.t2 = :one OR q.t3 = :one)) THEN :one ELSE :zero END) AS m3, sum(CASE WHEN (q.t4 = :one AND q.t4 = :one AND q.t5 = :one) THEN :one ELSE :zero END) AS m4, sum(CASE WHEN (q.t5 = :one AND q.t4 = :one AND q.t5 = :one) THEN :one ELSE :zero END) AS m5 
FROM (SELECT CASE WHEN (e0.status = :p0) THEN :one ELSE :zero END AS t0, CASE WHEN (e0.email IS NULL OR e0.email = :p1) THEN :one ELSE :zero END AS t1, CASE WHEN (e0.salary IS NULL) THEN :one ELSE :zero END AS t2, CASE WHEN (e0.department_id IS NULL) THEN :one ELSE :zero END AS t3, CASE WHEN (e0.status = :p2) THEN :one ELSE :zero END AS t4, CASE WHEN (e0.termination_date IS NULL) THEN :one ELSE :zero END AS t5 
FROM hr.[Employee] AS e0 
WHERE e0.status = :p0 AND (e0.email IS NULL OR e0.email = :p1 OR e0.salary IS NULL OR e0.department_id IS NULL) OR e0.status = :p2 AND e0.termination_date IS NULL) AS q
